<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Flight; use Illuminate\Http\Request; use Illuminate\Validation\ValidationException;
class FlightController extends Controller { private function rules():array{return ['flight_code'=>'required|string|max:30|unique:flights,flight_code','origin'=>'required|string|max:100','destination'=>'required|string|max:100|different:origin','departure'=>'required|date','arrival'=>'required|date|after:departure','aircraft_id'=>'required|exists:aircraft,id','pilot_id'=>'required|exists:pilots,id','status'=>'required|string|max:40'];} public function index(Request $r){$q=Flight::with(['aircraft','pilot']);if($r->filled('q')) { $term=$r->q; $q->where(fn($s)=>$s->where('flight_code','like',"%$term%")->orWhere('origin','like',"%$term%")->orWhere('destination','like',"%$term%")); }return $q->latest('departure')->paginate(15);} public function store(Request $r){$d=$r->validate($this->rules());return response()->json(Flight::create($d)->load(['aircraft','pilot']),201);} public function show(Flight $flight){return $flight->load(['aircraft','pilot']);} public function update(Request $r,Flight $flight){$rules=$this->rules();$rules['flight_code']='sometimes|required|string|max:30|unique:flights,flight_code,'.$flight->id;foreach(['origin','destination','departure','arrival','aircraft_id','pilot_id','status'] as $k)$rules[$k]=str_replace('required|','sometimes|required|',$rules[$k]);$d=$r->validate($rules);$flight->update($d);return $flight->fresh()->load(['aircraft','pilot']);} public function destroy(Flight $flight){$flight->delete();return response()->json(['message'=>'پرواز حذف شد']);} }
